<?php
namespace App\Http\Controllers\Dashboard;
use App\Http\Controllers\Controller; use Illuminate\Http\Request;
class TireController extends Controller { public function edit(Request $request) { $registration=$request->user()->registrations()->with('package','motorcycle','tireRequest')->latest()->firstOrFail(); abort_unless($request->user()->can('view',$registration),403); return view('dashboard.tires', compact('registration')); } public function update(Request $request) { $registration=$request->user()->registrations()->with('package','motorcycle')->latest()->firstOrFail(); abort_if(! $registration->requiresMotorcycle(), 404); $data=$request->validate(['brings_own_tires'=>['nullable','boolean'],'own_extra_sets_count'=>['required','integer','min:0','max:2'],'wants_tire_service'=>['nullable','boolean'],'wants_to_order_tires'=>['nullable','boolean'],'preferred_brand'=>['nullable','string','max:255'],'front_tire_size'=>['nullable','string','max:255'],'rear_tire_size'=>['nullable','string','max:255'],'compound_preference'=>['nullable','string','max:255'],'notes'=>['nullable','string']]); $registration->tireRequest()->updateOrCreate(['registration_id'=>$registration->id],$data+['motorcycle_id'=>$registration->motorcycle?->id,'brings_own_tires'=>$request->boolean('brings_own_tires'),'wants_tire_service'=>$request->boolean('wants_tire_service'),'wants_to_order_tires'=>$request->boolean('wants_to_order_tires')]); return back()->with('status','Tires saved'); } }
